//! Admitted same-connection conflict resolution, exact typed primitives remain host.
#[derive(Debug,PartialEq,Eq)]pub enum Error<E>{Callback(E),Invalid,Overflow,Rejected(&'static str)}
#[derive(Clone,Copy,Debug)]pub struct Metadata{pub present:bool,pub revision:i64,pub local:i64,pub remote:i64,pub tombstone:bool,pub retain:bool}
pub trait Backend{type Error;fn ready(&mut self)->Result<(),Self::Error>;fn metadata(&mut self)->Result<Option<Metadata>,Self::Error>;fn hash_matches(&mut self)->Result<bool,Self::Error>;fn skip(&mut self)->Result<(),Self::Error>;fn prepare(&mut self,next:i64,retain:bool)->Result<(),Self::Error>;fn domain(&mut self)->Result<(),Self::Error>;fn delete(&mut self)->Result<(),Self::Error>;fn revision(&mut self,next:i64)->Result<(),Self::Error>;fn outbox(&mut self)->Result<(),Self::Error>;fn resolve(&mut self)->Result<(),Self::Error>;}
pub fn execute<B:Backend>(b:&mut B)->Result<bool,Error<B::Error>>{
 b.ready().map_err(Error::Callback)?;let Some(m)=b.metadata().map_err(Error::Callback)? else{b.skip().map_err(Error::Callback)?;return Ok(false)};
 if if m.present{m.revision!=m.local||!b.hash_matches().map_err(Error::Callback)?}else{m.local!=0}{b.skip().map_err(Error::Callback)?;return Ok(false)}
 if m.retain&&!m.present{b.skip().map_err(Error::Callback)?;return Ok(false)}
 let next=m.revision.checked_add(1).ok_or(Error::Overflow)?;
 if if m.retain{m.remote<0}else{m.remote<=0}{return Err(Error::Rejected("remote_record_missing_accept_unavailable"))}
 if m.retain&&m.tombstone{return Err(Error::Rejected("keep_local_unavailable_server_tombstone"))}
 b.prepare(next,m.retain).map_err(Error::Callback)?;if !m.retain{b.domain().map_err(Error::Callback)?;}
 b.delete().map_err(Error::Callback)?;b.revision(next).map_err(Error::Callback)?;if m.retain{b.outbox().map_err(Error::Callback)?;}b.resolve().map_err(Error::Callback)?;Ok(true)
}
#[cfg(test)]mod tests{use super::*;struct P{trace:Vec<&'static str>,cut:usize,m:Option<Metadata>,hash:bool}impl P{fn new()->Self{Self{trace:vec![],cut:0,m:Some(Metadata{present:true,revision:7,local:7,remote:9,tombstone:false,retain:false}),hash:true}}fn hit(&mut self,n:&'static str)->Result<(),usize>{self.trace.push(n);if self.trace.len()==self.cut{Err(self.cut)}else{Ok(())}}}impl Backend for P{type Error=usize;fn ready(&mut self)->Result<(),usize>{self.hit("ready")}fn metadata(&mut self)->Result<Option<Metadata>,usize>{self.hit("metadata")?;Ok(self.m)}fn hash_matches(&mut self)->Result<bool,usize>{self.hit("hash")?;Ok(self.hash)}fn skip(&mut self)->Result<(),usize>{self.hit("skip")}fn prepare(&mut self,n:i64,r:bool)->Result<(),usize>{let m=self.m.unwrap();assert_eq!(n,m.revision+1);assert_eq!(r,m.retain);self.hit("prepare")}fn domain(&mut self)->Result<(),usize>{self.hit("domain")}fn delete(&mut self)->Result<(),usize>{self.hit("delete")}fn revision(&mut self,n:i64)->Result<(),usize>{assert_eq!(n,self.m.unwrap().revision+1);self.hit("revision")}fn outbox(&mut self)->Result<(),usize>{self.hit("outbox")}fn resolve(&mut self)->Result<(),usize>{self.hit("resolve")}}
#[test]fn both_branches_exact_order_every_callback_cutoff(){for retain in [false,true]{let mut p=P::new();p.m.as_mut().unwrap().retain=retain;assert_eq!(execute(&mut p),Ok(true));let expected=if retain{vec!["ready","metadata","hash","prepare","delete","revision","outbox","resolve"]}else{vec!["ready","metadata","hash","prepare","domain","delete","revision","resolve"]};assert_eq!(p.trace,expected);for cut in 1..=expected.len(){let mut p=P::new();p.m.as_mut().unwrap().retain=retain;p.cut=cut;assert_eq!(execute(&mut p),Err(Error::Callback(cut)));assert_eq!(p.trace,expected[..cut]);}}}
#[test]fn skip_short_circuit_and_absent_revision(){for case in 0..5{let mut p=P::new();match case{0=>p.m=None,1=>p.m.as_mut().unwrap().local=8,2=>p.hash=false,3=>{let m=p.m.as_mut().unwrap();m.present=false;m.local=1;},_=>{let m=p.m.as_mut().unwrap();m.present=false;m.local=0;m.retain=true;}}assert_eq!(execute(&mut p),Ok(false));assert_eq!(p.trace,if case==2{vec!["ready","metadata","hash","skip"]}else{vec!["ready","metadata","skip"]});}let mut p=P::new();let m=p.m.as_mut().unwrap();m.present=false;m.local=0;m.revision=0;assert_eq!(execute(&mut p),Ok(true));assert!(!p.trace.contains(&"hash"));}
#[test]fn signed_boundaries_overflow_before_policy_and_rejection_before_prepare(){for retain in [false,true]{for revision in [i64::MIN,-1,0,i64::MAX-1]{let mut p=P::new();let m=p.m.as_mut().unwrap();m.revision=revision;m.local=revision;m.retain=retain;m.remote=if retain{0}else{i64::MAX};assert_eq!(execute(&mut p),Ok(true));}for remote in [i64::MIN,-1,0]{let mut p=P::new();let m=p.m.as_mut().unwrap();m.retain=retain;m.remote=remote;assert_eq!(execute(&mut p),if retain&&remote==0{Ok(true)}else{Err(Error::Rejected("remote_record_missing_accept_unavailable"))});}let mut p=P::new();let m=p.m.as_mut().unwrap();m.retain=retain;m.revision=i64::MAX;m.local=i64::MAX;m.remote=-1;m.tombstone=true;assert_eq!(execute(&mut p),Err(Error::Overflow));assert_eq!(p.trace,vec!["ready","metadata","hash"]);}let mut p=P::new();let m=p.m.as_mut().unwrap();m.retain=true;m.tombstone=true;assert_eq!(execute(&mut p),Err(Error::Rejected("keep_local_unavailable_server_tombstone")));assert_eq!(p.trace,vec!["ready","metadata","hash"]);}}
